observation.command:
cat > /tmp/verify.php <<'EOF'
<?php
$profile = 'openculturas';
$info = \Drupal::service('extension.list.profile')->getExtensionInfo($profile);
$list = $info['install'] ?? [];
$m = \Drupal::service('module_handler');
$missing = [];
foreach ($list as $entry) {
  [$proj, $mod] = array_pad(explode(':', $entry, 2), 2, null);
  $name = $mod ?? $proj;
  if (!$m->moduleExists($name)) $missing[] = $entry;
}
echo "declared: " . count($list) . PHP_EOL;
echo "not enabled: " . count($missing) . PHP_EOL;
echo implode("\n", $missing) . PHP_EOL;
EOF
cd /workspace && cp /tmp/verify.php /workspace/verify_tmp.php && su ddevuser -c "ddev drush php:script verify_tmp.php" 2>&1 | tail -30; rm -f /workspace/verify_tmp.php
